<script setup lang="ts">
import { computed,onBeforeUnmount,ref,watch } from 'vue';
import { useTelephoneStore } from '../../stores/telephone';
import { useRoomStore } from '../../stores/room';
import { usePartyActionsStore } from '../../stores/party-actions';
import type { DrawingTool } from '../../contracts/drawing';
import TelephoneCanvas from '../../components/TelephoneCanvas.vue';
import DrawingToolButton from '../../components/DrawingToolButton.vue';
import RoomCountdown from '../../components/RoomCountdown.vue';
import UiButton from '../../components/UiButton.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import StatusSlot from '../../components/StatusSlot.vue';
const telephone=useTelephoneStore(),room=useRoomStore(),actions=usePartyActionsStore(),state=computed(()=>telephone.state!),confirm=ref<InstanceType<typeof ConfirmDialog>|null>(null),mode=ref('brush'),color=ref('#273942'),size=ref(6),book=ref(0),composing=ref(false);
const tools:[string,string][]=[['brush','畫筆'],['erase','橡皮擦'],['line','直線'],['rect','空心矩形'],['ellipse','空心橢圓'],['rectFilled','實心矩形'],['ellipseFilled','實心橢圓'],['fill','油漆桶：填滿連續區域']];
const tool=computed(()=>mode.value.replace('Filled','') as DrawingTool),filled=computed(()=>mode.value.endsWith('Filled')),selected=computed(()=>state.value.books[book.value]||state.value.books[0]),points=computed(()=>telephone.strokes.reduce((sum,s)=>sum+s.points.length,0)),blocked=computed(()=>!telephone.editable||telephone.activeStroke),heading=computed(()=>state.value.phase==='waiting'?'從一句話，傳出意想不到的故事':state.value.phase==='finished'?state.value.interrupted?'傳遞中止，回看已送出的頁面':'全部揭曉，看看故事如何變形':state.value.task?.submitted?'本頁已送出，等待時間到':state.value.task?.kind==='drawing'?'把上一頁文字，畫成一張圖':'只看上一張圖，猜一句話');
const syncMessage=computed(()=>state.value.phase!=='passing'?'固定入座順序，不計個人分數。':telephone.expired?'本頁截止，正在傳下一頁；以伺服器接受的內容為準。':state.value.task?.submitted?'送出後不能修改，其他頁面仍保密。':telephone.saving?'正在同步私人草稿…':telephone.dirty?'有本地內容尚未同步；到時只採用伺服器接受的內容。':'目前草稿已與伺服器同步。');
watch([()=>room.scope,()=>state.value.stepId,()=>state.value.phase,()=>state.value.task?.submitted,()=>telephone.expired],()=>{confirm.value?.cancel();composing.value=false;});
watch(()=>state.value.phase,phase=>{if(phase!=='finished')book.value=0;});
async function clear(){if(blocked.value)return;const scope=room.scope,step=state.value.stepId;if(await confirm.value?.ask('清除這一頁的本地畫布並同步空白草稿？這個動作無法復原。','清除畫布'))if(scope===room.scope&&step===state.value.stepId&&!blocked.value)telephone.clear();}
async function skip(){if(blocked.value)return;const scope=room.scope,step=state.value.stepId;if(await confirm.value?.ask('這頁會標記為略過，已畫或已輸入的內容不會送出。','略過這頁'))if(scope===room.scope&&step===state.value.stepId&&!blocked.value)await telephone.submit(true);}
function input(event:Event){if(composing.value)return;const target=event.target as HTMLInputElement;telephone.changeText(target.value);target.value=telephone.text;}
function visibility(){if(document.hidden)confirm.value?.cancel();}
document.addEventListener('visibilitychange',visibility);onBeforeUnmount(()=>document.removeEventListener('visibilitychange',visibility));
</script>
<template><section class="vue-game-panel vue-telephone-stage" aria-labelledby="telephoneHeading"><header><small>DRAW · GUESS · PASS IT ON</small><h1 id="telephoneHeading">{{ heading }}</h1><p>每頁 90 秒，時間到自動傳頁；全員提早送出也不會提前換頁。</p></header>
 <div class="vue-telephone-clock"><RoomCountdown :deadline="state.deadline" :duration="90000" :offset="telephone.offset" :epoch="state.stepId||'waiting'" :now="telephone.now" caption="傳頁剩餘時間" empty-value="每頁 90 秒" urgent /></div>
 <div class="vue-telephone-live">
  <section v-if="state.phase==='passing'&&state.task" class="vue-telephone-task" data-private><div class="vue-telephone-previous"><template v-if="state.task.previous.kind==='text'"><small>上一頁文字 · 只給你看</small><h2>{{ state.task.previous.text }}</h2></template><template v-else><h2>上一位玩家的畫作 · 只給你看</h2><TelephoneCanvas :strokes="state.task.previous.strokes||[]" :epoch="state.stepId+':previous'" label="上一位玩家的畫作" /><p v-if="state.task.previous.skipped">上一頁略過；可以自由猜一句話或略過本頁。</p></template></div>
   <template v-if="!state.task.submitted"><template v-if="state.task.kind==='drawing'"><div class="vue-telephone-tools" role="group" aria-label="私人畫布工具"><DrawingToolButton v-for="[value,label] in tools" :key="value" :tool="value" :label="label" :selected="mode===value" :disabled="blocked" @click="mode=value" /><DrawingToolButton tool="undo" label="復原上一筆" :disabled="blocked||!telephone.strokes.length" @click="telephone.undo()" /><DrawingToolButton tool="clear" label="清除畫布" :disabled="blocked||!telephone.strokes.length" @click="clear" /></div><div class="vue-telephone-colors"><label>顏色<input v-model="color" type="color" aria-label="選擇畫筆顏色" :disabled="blocked"></label><details><summary>調色盤</summary><div><button v-for="shade in ['#273942','#ffffff','#e45757','#f3a844','#f4d264','#6bb879','#5197ca','#8058ad','#d979a7','#8b6348']" :key="shade" type="button" :style="{background:shade}" :aria-label="'選擇顏色 '+shade" :disabled="blocked" @click="color=shade" /></div></details><label class="vue-telephone-size">筆刷<input v-model.number="size" type="range" min="1" max="40" :disabled="blocked" aria-label="畫筆寬度"><output>{{ size }}</output></label></div>
    <TelephoneCanvas :strokes="telephone.strokes" :epoch="state.stepId||''" label="你的私人畫布；可用滑鼠、觸控、方向鍵與空白鍵作畫" :editable="telephone.editable" :tool="tool" :color="color" :size="size" :filled="filled" @change="telephone.changeStrokes" @active="telephone.activeStroke=$event" @notice="telephone.notice=$event" /><p class="vue-telephone-quota">本地 {{ telephone.strokes.length }}／100 筆 · {{ points }}／3,000 點 · 伺服器已接受 {{ telephone.acceptedCount }} 筆</p></template>
    <label v-else class="vue-telephone-guess">你覺得圖上是什麼？<input :value="telephone.text" autocomplete="off" :disabled="!telephone.editable" aria-describedby="telephoneGuessCount" @input="input" @compositionstart="composing=true" @compositionend="composing=false;input($event)"><span id="telephoneGuessCount">{{ [...telephone.text].length }}／80 字 · 已接受 {{ telephone.acceptedCount }} 字；不能換行</span></label>
   </template><div v-else class="vue-telephone-submitted"><strong>這頁已完成</strong><p>時間到才傳下一頁。可以看看玩家狀態，或在聊天室聊聊天。</p></div>
  </section>
  <section v-else-if="state.phase==='finished'" class="vue-telephone-review"><label>選擇傳遞簿<select v-model.number="book"><option v-for="(value,index) in state.books" :key="value.ownerId" :value="index">{{ value.ownerName }} 的故事</option></select></label><p v-if="state.interrupted">有人離席，本場中止；只保留已送出的頁面，不包含尚未送出的私人草稿。</p><template v-if="selected"><h2>{{ selected.ownerName }} 的傳遞簿</h2><article v-for="(page,index) in selected.pages" :key="selected.ownerId+':'+index"><h3>{{ index?'第 '+index+' 頁':'起始情境' }} · {{ page.authorName }}</h3><p v-if="page.skipped">本頁略過{{ page.timedOut?' · 時間到時沒有已同步的內容':'' }}</p><template v-else><TelephoneCanvas v-if="page.kind==='drawing'" :strokes="page.strokes||[]" :epoch="state.stepId+':'+selected.ownerId+':'+index" :label="page.authorName+' 的第 '+index+' 頁畫作'" /><p v-else>{{ page.text }}</p><small v-if="page.timedOut">時間到，採用已同步的私人草稿</small></template></article></template><p v-else>尚無可揭曉的傳遞簿。</p></section>
  <section v-else class="vue-telephone-waiting"><img :src="room.host?'/assets/stitch/waiting-host.jpg':'/assets/stitch/waiting-guest.jpg'" alt=""><h2>一起畫，一起猜，最後一起笑</h2><p>邀請 3–8 位朋友入座，或加入腳本夥伴試玩。開始後每個人只看上一頁，最後才揭曉完整故事。</p></section>
 </div>
 <div class="vue-telephone-status"><p>{{ syncMessage }}</p><StatusSlot :message="actions.notice||telephone.notice||telephone.storageNotice" :error="(!actions.pending&&!!actions.notice)||!!telephone.storageNotice" /></div>
 <footer class="vue-telephone-actions"><template v-if="state.phase==='passing'&&!state.task?.submitted"><UiButton icon="refresh" label="同步草稿" :pending="telephone.saving" :disabled="!telephone.allowed||telephone.finishing||room.busy||!telephone.dirty" @click="telephone.sync()" /><UiButton icon="check" label="確認送出這頁" :pending="telephone.finishing" :disabled="blocked||composing||(state.task?.kind==='drawing'?!telephone.strokes.length:!telephone.text.trim())" @click="telephone.submit()" /><UiButton label="略過這頁" :disabled="blocked" @click="skip" /></template><UiButton v-if="actions.canRetry" icon="refresh" label="重試同一操作" :disabled="room.busy||!room.connected" @click="actions.retrySame()" /><span v-if="state.phase==='passing'">送出後不能修改。</span><span v-else>固定順序傳遞，每本故事都有不同的驚喜。</span></footer>
</section><ConfirmDialog ref="confirm" /></template>
